# -*- coding: utf-8 -*-
# Ce script met a jour tous les fichiers necessaires pour la nouvelle version de l'appli
# (repertoire d'exercices, dates de camp, mode 'a fond', badges).
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update.py
import pathlib

FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod (voir src/routes/exercises.ts et src/routes/programs.ts).\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  programs       UserProgram[]\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  programs      UserProgram[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  members   CampMembership[]\n  programs  UserProgram[]\n  logs      ExerciseLog[]\n}\n\nmodel CampExercise {\n  id         String   @id @default(cuid())\n  campId     String\n  exerciseId String\n  camp       Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise   Exercise @relation(fields: [exerciseId], references: [id])\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel UserProgram {\n  id             String         @id @default(cuid())\n  userId         String\n  campId         String\n  exerciseId     String\n  targetSets     Int\n  targetMode     String         @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?           // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String         // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?        // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?           // utilise si EVERY_N_DAYS\n  startDate      DateTime       @default(now())\n  active         Boolean        @default(true)\n  createdAt      DateTime       @default(now())\n\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n\n  @@unique([userId, campId, exerciseId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n'
FILES['backend/src/utils/badges.ts'] = 'import { prisma } from "../lib/prisma";\nimport { toDayStart } from "./recurrence";\n\n// Catalogue des badges disponibles. Purement individuel : aucune comparaison entre utilisateurs.\nexport interface BadgeDefinition {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport const BADGE_CATALOG: BadgeDefinition[] = [\n  { key: "STREAK_3", name: "3 jours d\'affilee", description: "Une seance realisee chaque jour, 3 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_7", name: "1 semaine reguliere", description: "Une seance realisee chaque jour, 7 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_30", name: "1 mois de regularite", description: "Une seance realisee chaque jour, 30 jours de suite.", emoji: "🏅" },\n  { key: "STREAK_100", name: "100 jours de suite", description: "Une seance realisee chaque jour, 100 jours de suite.", emoji: "🏆" },\n  { key: "TOTAL_10", name: "10 seances", description: "10 seances validees au total.", emoji: "✅" },\n  { key: "TOTAL_50", name: "50 seances", description: "50 seances validees au total.", emoji: "⭐" },\n  { key: "TOTAL_100", name: "100 seances", description: "100 seances validees au total.", emoji: "🌟" },\n  { key: "TOTAL_500", name: "500 seances", description: "500 seances validees au total.", emoji: "💎" },\n];\n\nconst STREAK_THRESHOLDS: [number, string][] = [\n  [100, "STREAK_100"],\n  [30, "STREAK_30"],\n  [7, "STREAK_7"],\n  [3, "STREAK_3"],\n];\n\nconst TOTAL_THRESHOLDS: [number, string][] = [\n  [500, "TOTAL_500"],\n  [100, "TOTAL_100"],\n  [50, "TOTAL_50"],\n  [10, "TOTAL_10"],\n];\n\n// Calcule le plus long "streak" en cours (jours consecutifs avec au moins une seance,\n// tous camps/exercices confondus), en remontant depuis aujourd\'hui ou hier.\nfunction computeGlobalStreak(distinctDates: Set<string>, today: Date): number {\n  const start = toDayStart(today);\n  // Si rien n\'est fait aujourd\'hui, on tolere et on part d\'hier pour ne pas casser la serie\n  // en cours de journee.\n  let cursor = new Date(start);\n  if (!distinctDates.has(cursor.toISOString().slice(0, 10))) {\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  let streak = 0;\n  for (let i = 0; i < 3650; i++) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (!distinctDates.has(key)) break;\n    streak++;\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  return streak;\n}\n\n// Recalcule les stats de l\'utilisateur et attribue tout nouveau badge merite.\n// Appele apres chaque validation de seance. Idempotent (un badge n\'est jamais attribue deux fois).\nexport async function checkAndAwardBadges(userId: string): Promise<BadgeDefinition[]> {\n  const logs = await prisma.exerciseLog.findMany({\n    where: { userId },\n    select: { date: true },\n  });\n\n  const distinctDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n  const totalSessions = logs.length;\n  const streak = computeGlobalStreak(distinctDates, new Date());\n\n  const earnedKeys = new Set<string>();\n  // On attribue TOUS les paliers deja franchis (pas seulement le plus haut), pour garder\n  // l\'historique des badges obtenus meme si la serie casse ensuite.\n  for (const [threshold, key] of STREAK_THRESHOLDS) {\n    if (streak >= threshold) earnedKeys.add(key);\n  }\n  for (const [threshold, key] of TOTAL_THRESHOLDS) {\n    if (totalSessions >= threshold) earnedKeys.add(key);\n  }\n\n  if (earnedKeys.size === 0) return [];\n\n  const alreadyEarned = await prisma.userBadge.findMany({ where: { userId }, select: { badgeKey: true } });\n  const alreadyEarnedKeys = new Set(alreadyEarned.map((b) => b.badgeKey));\n\n  const newlyEarned = [...earnedKeys].filter((k) => !alreadyEarnedKeys.has(k));\n  if (newlyEarned.length === 0) return [];\n\n  await prisma.userBadge.createMany({\n    data: newlyEarned.map((badgeKey) => ({ userId, badgeKey })),\n    skipDuplicates: true,\n  });\n\n  return BADGE_CATALOG.filter((b) => newlyEarned.includes(b.key));\n}\n'
FILES['backend/src/routes/badges.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { BADGE_CATALOG } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie les badges obtenus par l\'utilisateur, ainsi que le catalogue complet\n// (pour pouvoir afficher les badges pas encore obtenus en "verrouille" si souhaite).\nrouter.get("/", async (req: AuthRequest, res) => {\n  const earned = await prisma.userBadge.findMany({\n    where: { userId: req.userId },\n    orderBy: { earnedAt: "asc" },\n  });\n\n  const earnedMap = new Map(earned.map((b) => [b.badgeKey, b.earnedAt]));\n\n  const badges = BADGE_CATALOG.map((def) => ({\n    ...def,\n    earned: earnedMap.has(def.key),\n    earnedAt: earnedMap.get(def.key) ?? null,\n  }));\n\n  res.json(badges);\n});\n\nexport default router;\n'
FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n});\n\n// Cree un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le createur devient automatiquement membre du camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, exerciseIds, startDate, endDate } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit etre apres la date de debut." });\n  }\n\n  // On genere un code unique (tres faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId! }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es deja membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  res.json(memberships.map((m) => m.camp));\n});\n\n// Detail d\'un camp (verifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  res.json(camp);\n});\n\nexport default router;\n'
FILES['backend/src/routes/programs.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst recurrenceSchema = z.discriminatedUnion("recurrenceType", [\n  z.object({ recurrenceType: z.literal("DAILY") }),\n  z.object({ recurrenceType: z.literal("WEEKLY"), daysOfWeek: z.array(z.number().min(0).max(6)).min(1) }),\n  z.object({ recurrenceType: z.literal("EVERY_N_DAYS"), intervalDays: z.number().min(1) }),\n]);\n\nconst targetSchema = z.discriminatedUnion("targetMode", [\n  z.object({ targetMode: z.literal("FIXED"), targetValue: z.number().min(1) }),\n  z.object({ targetMode: z.literal("MAX"), targetValue: z.number().min(1).optional() }),\n]);\n\nconst upsertSchema = z\n  .object({\n    campId: z.string(),\n    exerciseId: z.string(),\n    targetSets: z.number().min(1),\n  })\n  .and(targetSchema)\n  .and(recurrenceSchema);\n\n// Cree ou met a jour le programme personnel d\'un utilisateur pour un exercice donne d\'un camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = upsertSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  // Verifie que l\'utilisateur est bien membre du camp, et que l\'exercice en fait partie\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: data.campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const campExercise = await prisma.campExercise.findUnique({\n    where: { campId_exerciseId: { campId: data.campId, exerciseId: data.exerciseId } },\n  });\n  if (!campExercise) return res.status(400).json({ error: "Cet exercice ne fait pas partie du camp." });\n\n  const program = await prisma.userProgram.upsert({\n    where: {\n      userId_campId_exerciseId: { userId: req.userId!, campId: data.campId, exerciseId: data.exerciseId },\n    },\n    create: {\n      userId: req.userId!,\n      campId: data.campId,\n      exerciseId: data.exerciseId,\n      targetSets: data.targetSets,\n      targetMode: data.targetMode,\n      targetValue: data.targetMode === "FIXED" ? data.targetValue : data.targetValue ?? null,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n    },\n    update: {\n      targetSets: data.targetSets,\n      targetMode: data.targetMode,\n      targetValue: data.targetMode === "FIXED" ? data.targetValue : data.targetValue ?? null,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n      active: true,\n    },\n  });\n\n  res.status(201).json(program);\n});\n\n// Liste les programmes de l\'utilisateur pour un camp donne\nrouter.get("/", async (req: AuthRequest, res) => {\n  const campId = req.query.campId as string | undefined;\n  if (!campId) return res.status(400).json({ error: "Le parametre campId est requis." });\n\n  const programs = await prisma.userProgram.findMany({\n    where: { userId: req.userId, campId, active: true },\n    include: { exercise: true },\n  });\n  res.json(programs);\n});\n\n// Desactive un programme (l\'utilisateur arrete de suivre cet exercice dans ce camp)\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const program = await prisma.userProgram.findUnique({ where: { id: req.params.id } });\n  if (!program || program.userId !== req.userId) {\n    return res.status(404).json({ error: "Programme introuvable." });\n  }\n  await prisma.userProgram.update({ where: { id: req.params.id }, data: { active: false } });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/routes/exercises.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste le catalogue complet : exercices par defaut + exercices "maison" ajoutes par les utilisateurs\nrouter.get("/", async (_req, res) => {\n  const exercises = await prisma.exercise.findMany({ orderBy: [{ isCustom: "asc" }, { name: "asc" }] });\n  res.json(exercises);\n});\n\n// Repertoire complet du catalogue avec, pour chaque exercice, son nombre d\'utilisations\n// (nombre de camps distincts qui l\'utilisent, tous camps confondus -- meme ceux dont\n// l\'utilisateur ne fait pas partie). Purement statistique, aucun detail sur les camps n\'est expose.\nrouter.get("/stats", async (_req, res) => {\n  const exercises = await prisma.exercise.findMany({\n    orderBy: [{ isCustom: "asc" }, { name: "asc" }],\n    include: { _count: { select: { campExercises: true } } },\n  });\n  res.json(\n    exercises.map((e) => ({\n      id: e.id,\n      name: e.name,\n      description: e.description,\n      unit: e.unit,\n      isCustom: e.isCustom,\n      campCount: e._count.campExercises,\n    }))\n  );\n});\n\nconst createSchema = z.object({\n  name: z.string().min(1, "Le nom de l\'exercice est requis."),\n  description: z.string().optional(),\n  unit: z.enum(["REPS", "SECONDS"]),\n});\n\n// Permet d\'ajouter un exercice "maison" au catalogue partage\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const exercise = await prisma.exercise.create({\n    data: { ...parsed.data, isCustom: true, createdById: req.userId },\n  });\n  res.status(201).json(exercise);\n});\n\nexport default router;\n'
FILES['backend/src/routes/today.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie, pour aujourd\'hui, tous les exercices dus (tous camps confondus)\n// avec l\'info si deja fait ou non.\nrouter.get("/", async (req: AuthRequest, res) => {\n  const today = toDayStart(new Date());\n\n  const programs = await prisma.userProgram.findMany({\n    where: { userId: req.userId, active: true },\n    include: { exercise: true, camp: true },\n  });\n\n  // On ne propose que les programmes dont le camp est en cours (entre sa date de debut et de fin, si definies)\n  const withinCampDates = programs.filter((p) => {\n    if (p.camp.startDate && today.getTime() < toDayStart(p.camp.startDate).getTime()) return false;\n    if (p.camp.endDate && today.getTime() > toDayStart(p.camp.endDate).getTime()) return false;\n    return true;\n  });\n\n  const dueToday = withinCampDates.filter((p) => isDueOnDate(p, today));\n\n  const logsToday = await prisma.exerciseLog.findMany({\n    where: { userId: req.userId, date: today },\n  });\n  const logByProgram = new Map(logsToday.map((l) => [`${l.campId}:${l.exerciseId}`, l]));\n\n  // Pour les exercices en mode "MAX", on va chercher le record personnel precedent a titre de reference\n  const maxPrograms = dueToday.filter((p) => p.targetMode === "MAX");\n  const bestByProgram = new Map<string, number>();\n  for (const p of maxPrograms) {\n    const best = await prisma.exerciseLog.findFirst({\n      where: { userId: req.userId, campId: p.campId, exerciseId: p.exerciseId },\n      orderBy: { valueDone: "desc" },\n    });\n    if (best) bestByProgram.set(`${p.campId}:${p.exerciseId}`, best.valueDone);\n  }\n\n  const result = dueToday.map((p) => {\n    const key = `${p.campId}:${p.exerciseId}`;\n    const log = logByProgram.get(key);\n    return {\n      programId: p.id,\n      campId: p.campId,\n      campName: p.camp.name,\n      exerciseId: p.exerciseId,\n      exerciseName: p.exercise.name,\n      unit: p.exercise.unit,\n      targetSets: p.targetSets,\n      targetMode: p.targetMode,\n      targetValue: p.targetValue,\n      personalBest: bestByProgram.get(key) ?? null,\n      done: !!log,\n      log: log ? { setsDone: log.setsDone, valueDone: log.valueDone } : null,\n    };\n  });\n\n  res.json({ date: today.toISOString().slice(0, 10), items: result });\n});\n\nexport default router;\n'
FILES['backend/src/routes/logs.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { toDayStart } from "../utils/recurrence";\nimport { checkAndAwardBadges } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst logSchema = z.object({\n  campId: z.string(),\n  exerciseId: z.string(),\n  setsDone: z.number().min(1),\n  valueDone: z.number().min(0),\n  date: z.string().optional(), // optionnel, permet de rattraper un jour passe ; defaut = aujourd\'hui\n});\n\n// Enregistre (ou met a jour) la realisation d\'un exercice pour une journee donnee.\n// L\'idee n\'est pas la performance, mais la regularite : un log = "je l\'ai fait aujourd\'hui".\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = logSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { campId, exerciseId, setsDone, valueDone, date } = parsed.data;\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const day = toDayStart(date ? new Date(date) : new Date());\n\n  const log = await prisma.exerciseLog.upsert({\n    where: { userId_campId_exerciseId_date: { userId: req.userId!, campId, exerciseId, date: day } },\n    create: { userId: req.userId!, campId, exerciseId, date: day, setsDone, valueDone, completed: true },\n    update: { setsDone, valueDone, completed: true },\n  });\n\n  const newBadges = await checkAndAwardBadges(req.userId!);\n\n  res.status(201).json({ log, newBadges });\n});\n\n// Permet d\'annuler un log (ex: coche par erreur)\nrouter.delete("/", async (req: AuthRequest, res) => {\n  const campId = req.query.campId as string;\n  const exerciseId = req.query.exerciseId as string;\n  const dateStr = req.query.date as string | undefined;\n  if (!campId || !exerciseId) {\n    return res.status(400).json({ error: "campId et exerciseId sont requis." });\n  }\n  const day = toDayStart(dateStr ? new Date(dateStr) : new Date());\n\n  await prisma.exerciseLog.deleteMany({\n    where: { userId: req.userId, campId, exerciseId, date: day },\n  });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport programRoutes from "./routes/programs";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/programs", programRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst navItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/profil", label: "Profil" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-6">\n          <div className="flex items-center gap-2 mb-8">\n            <span className="w-8 h-8 rounded bg-accent flex items-center justify-center font-display font-bold text-bg text-lg">\n              C\n            </span>\n            <span className="font-display text-lg tracking-wide uppercase">Camp</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {navItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <nav className="md:hidden flex justify-around bg-surface border-b border-border order-2">\n        {navItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 text-center py-3 text-xs font-medium ${isActive ? "text-accent" : "text-muted"}`\n            }\n          >\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n\n      <main className="flex-1 p-5 md:p-10 max-w-4xl mx-auto w-full">{children}</main>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/ProgramForm.tsx'] = 'import { useState } from "react";\nimport { api, ApiError } from "../api/client";\n\nexport interface Program {\n  id: string;\n  exerciseId: string;\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  recurrenceType: "DAILY" | "WEEKLY" | "EVERY_N_DAYS";\n  daysOfWeek: string | null;\n  intervalDays: number | null;\n}\n\ninterface Props {\n  campId: string;\n  exerciseId: string;\n  exerciseName: string;\n  unit: "REPS" | "SECONDS";\n  existing?: Program;\n  onSaved: () => void;\n  onCancel: () => void;\n}\n\nconst WEEKDAYS = [\n  { value: 1, label: "Lun" },\n  { value: 2, label: "Mar" },\n  { value: 3, label: "Mer" },\n  { value: 4, label: "Jeu" },\n  { value: 5, label: "Ven" },\n  { value: 6, label: "Sam" },\n  { value: 0, label: "Dim" },\n];\n\nexport default function ProgramForm({ campId, exerciseId, exerciseName, unit, existing, onSaved, onCancel }: Props) {\n  const [targetSets, setTargetSets] = useState(existing?.targetSets ?? 3);\n  const [targetMode, setTargetMode] = useState<"FIXED" | "MAX">(existing?.targetMode ?? "FIXED");\n  const [targetValue, setTargetValue] = useState(existing?.targetValue ?? (unit === "REPS" ? 10 : 30));\n  const [recurrenceType, setRecurrenceType] = useState<"DAILY" | "WEEKLY" | "EVERY_N_DAYS">(\n    existing?.recurrenceType ?? "DAILY"\n  );\n  const [daysOfWeek, setDaysOfWeek] = useState<number[]>(\n    existing?.daysOfWeek ? JSON.parse(existing.daysOfWeek) : [1, 3, 5]\n  );\n  const [intervalDays, setIntervalDays] = useState(existing?.intervalDays ?? 2);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  function toggleDay(day: number) {\n    setDaysOfWeek((prev) => (prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day].sort()));\n  }\n\n  async function save() {\n    setError(null);\n    if (recurrenceType === "WEEKLY" && daysOfWeek.length === 0) {\n      setError("Choisis au moins un jour de la semaine.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const payload: Record<string, unknown> = {\n        campId,\n        exerciseId,\n        targetSets,\n        targetMode,\n        recurrenceType,\n      };\n      if (targetMode === "FIXED") payload.targetValue = targetValue;\n      if (recurrenceType === "WEEKLY") payload.daysOfWeek = daysOfWeek;\n      if (recurrenceType === "EVERY_N_DAYS") payload.intervalDays = intervalDays;\n\n      await api.post("/programs", payload);\n      onSaved();\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible d\'enregistrer ce programme.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const unitLabel = unit === "REPS" ? "repetitions" : "secondes tenues";\n\n  return (\n    <div className="bg-surface2 border border-border rounded-lg p-4 space-y-4">\n      <h3 className="font-display uppercase tracking-wide text-sm">{exerciseName}</h3>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Type d\'objectif</label>\n        <div className="flex gap-1.5 mb-3">\n          <button\n            type="button"\n            onClick={() => setTargetMode("FIXED")}\n            className={`px-3 py-1.5 rounded text-xs border ${\n              targetMode === "FIXED" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n            }`}\n          >\n            Objectif chiffre\n          </button>\n          <button\n            type="button"\n            onClick={() => setTargetMode("MAX")}\n            className={`px-3 py-1.5 rounded text-xs border ${\n              targetMode === "MAX" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n            }`}\n          >\n            A fond (record perso)\n          </button>\n        </div>\n      </div>\n\n      <div className="grid grid-cols-2 gap-3">\n        <div>\n          <label className="block text-xs text-muted mb-1">Nombre de series</label>\n          <input\n            type="number"\n            min={1}\n            value={targetSets}\n            onChange={(e) => setTargetSets(Number(e.target.value))}\n            className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n          />\n        </div>\n        {targetMode === "FIXED" ? (\n          <div>\n            <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n            <input\n              type="number"\n              min={1}\n              value={targetValue}\n              onChange={(e) => setTargetValue(Number(e.target.value))}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n            />\n          </div>\n        ) : (\n          <div>\n            <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n            <div className="w-full bg-surface border border-dashed border-border rounded-md px-2 py-1.5 text-sm text-muted">\n              A fond, sans limite fixee\n            </div>\n          </div>\n        )}\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Frequence</label>\n        <select\n          value={recurrenceType}\n          onChange={(e) => setRecurrenceType(e.target.value as any)}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm mb-2"\n        >\n          <option value="DAILY">Tous les jours</option>\n          <option value="WEEKLY">Certains jours de la semaine</option>\n          <option value="EVERY_N_DAYS">Tous les X jours</option>\n        </select>\n\n        {recurrenceType === "WEEKLY" && (\n          <div className="flex flex-wrap gap-1.5">\n            {WEEKDAYS.map((d) => (\n              <button\n                type="button"\n                key={d.value}\n                onClick={() => toggleDay(d.value)}\n                className={`px-2.5 py-1 rounded text-xs border ${\n                  daysOfWeek.includes(d.value)\n                    ? "bg-accent/20 border-accent text-text"\n                    : "bg-surface border-border text-muted"\n                }`}\n              >\n                {d.label}\n              </button>\n            ))}\n          </div>\n        )}\n\n        {recurrenceType === "EVERY_N_DAYS" && (\n          <div className="flex items-center gap-2 text-sm">\n            <span className="text-muted">Tous les</span>\n            <input\n              type="number"\n              min={1}\n              value={intervalDays}\n              onChange={(e) => setIntervalDays(Number(e.target.value))}\n              className="w-16 bg-surface border border-border rounded-md px-2 py-1"\n            />\n            <span className="text-muted">jours</span>\n          </div>\n        )}\n      </div>\n\n      {error && <p className="text-sm text-accent">{error}</p>}\n\n      <div className="flex gap-2">\n        <button\n          onClick={save}\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-1.5 text-sm disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n        <button onClick={onCancel} className="text-muted hover:text-text text-sm px-2">\n          Annuler\n        </button>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport type { Exercise } from "../components/ExercisePicker";\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  code: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: { exercise: Exercise }[];\n  members: { user: { id: string; name: string } }[];\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: Program) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [programs, setPrograms] = useState<Program[]>([]);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n    api.get<Program[]>(`/programs?campId=${id}`).then(setPrograms);\n  }\n  useEffect(load, [id]);\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const programByExercise = new Map(programs.map((p) => [p.exerciseId, p]));\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-3">Mes exercices dans ce camp</h2>\n      <p className="text-muted text-sm mb-4">\n        Configure combien de series/repetitions tu veux faire, et a quelle frequence.\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map(({ exercise }) => {\n          const program = programByExercise.get(exercise.id);\n          const isEditing = editingExerciseId === exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={exercise.id}\n                campId={camp.id}\n                exerciseId={exercise.id}\n                exerciseName={exercise.name}\n                unit={exercise.unit}\n                existing={program}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          return (\n            <div\n              key={exercise.id}\n              className="bg-surface border border-border rounded-lg p-4 flex items-center justify-between flex-wrap gap-3"\n            >\n              <div>\n                <p className="font-medium">{exercise.name}</p>\n                {program ? (\n                  <p className="text-sm text-muted">\n                    {program.targetMode === "MAX"\n                      ? `${program.targetSets} serie${program.targetSets > 1 ? "s" : ""} a fond`\n                      : `${program.targetSets} x ${program.targetValue} ${exercise.unit === "REPS" ? "reps" : "sec"}`}{" "}\n                    · {RECURRENCE_LABEL[program.recurrenceType](program)}\n                  </p>\n                ) : (\n                  <p className="text-sm text-muted italic">Pas encore configure</p>\n                )}\n              </div>\n              <div className="flex gap-3 items-center">\n                {program && (\n                  <Link\n                    to={`/camps/${camp.id}/progression/${exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                )}\n                <button\n                  onClick={() => setEditingExerciseId(exercise.id)}\n                  className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                >\n                  {program ? "Modifier" : "Configurer"}\n                </button>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CreateCamp.tsx'] = 'import { FormEvent, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\nimport ExercisePicker from "../components/ExercisePicker";\n\nexport default function CreateCamp() {\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [selected, setSelected] = useState<string[]>([]);\n  const [startDate, setStartDate] = useState("");\n  const [endDate, setEndDate] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [createdCode, setCreatedCode] = useState<string | null>(null);\n  const [createdId, setCreatedId] = useState<string | null>(null);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    if (selected.length === 0) {\n      setError("Selectionne au moins un exercice.");\n      return;\n    }\n    if (startDate && endDate && endDate < startDate) {\n      setError("La date de fin doit etre apres la date de debut.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const camp = await api.post<{ id: string; code: string }>("/camps", {\n        name,\n        exerciseIds: selected,\n        startDate: startDate || null,\n        endDate: endDate || null,\n      });\n      setCreatedCode(camp.code);\n      setCreatedId(camp.id);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de creer le camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  if (createdCode && createdId) {\n    return (\n      <div className="max-w-md">\n        <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Camp cree !</h1>\n        <p className="text-muted text-sm mb-6">\n          Partage ce code pour inviter d\'autres personnes a rejoindre "{name}".\n        </p>\n        <div className="bg-surface border-2 border-dashed border-accent rounded-xl p-6 text-center mb-6">\n          <p className="text-xs uppercase tracking-widest text-muted mb-2">Code d\'invitation</p>\n          <p className="font-mono text-4xl tracking-[0.3em] text-accent">{createdCode}</p>\n        </div>\n        <button\n          onClick={() => navigate(`/camps/${createdId}`)}\n          className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2"\n        >\n          Configurer mon programme\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Nouveau camp</h1>\n      <p className="text-muted text-sm mb-6">\n        Choisis un nom et les exercices qui feront partie de ce camp. Chaque membre pourra ensuite definir son\n        propre nombre de series/repetitions et sa propre frequence.\n      </p>\n\n      <form onSubmit={onSubmit} className="space-y-5">\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="name">\n            Nom du camp\n          </label>\n          <input\n            id="name"\n            required\n            value={name}\n            onChange={(e) => setName(e.target.value)}\n            placeholder="Ex : Preparation pompiers volontaires"\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Exercices du camp</label>\n          <ExercisePicker selected={selected} onChange={setSelected} />\n        </div>\n\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="startDate">\n              Date de debut (optionnel)\n            </label>\n            <input\n              id="startDate"\n              type="date"\n              value={startDate}\n              onChange={(e) => setStartDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="endDate">\n              Date de fin (optionnel)\n            </label>\n            <input\n              id="endDate"\n              type="date"\n              value={endDate}\n              onChange={(e) => setEndDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Creation..." : "Creer le camp"}\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface TodayItem {\n  programId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  unit: "REPS" | "SECONDS";\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport default function Today() {\n  const [items, setItems] = useState<TodayItem[] | null>(null);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n\n  function load() {\n    api.get<{ date: string; items: TodayItem[] }>("/today").then((res) => setItems(res.items));\n  }\n  useEffect(load, []);\n\n  function startEditing(item: TodayItem) {\n    setEditingId(item.programId);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  async function confirm(item: TodayItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  const doneCount = items?.filter((i) => i.done).length ?? 0;\n  const total = items?.length ?? 0;\n\n  return (\n    <div className="max-w-xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Aujourd\'hui</h1>\n      <p className="text-muted text-sm mb-6">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} seance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Aucun exercice programme pour aujourd\'hui. Va configurer ton programme dans un de tes camps.\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {items?.map((item) => {\n          const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n          const isEditing = editingId === item.programId;\n\n          return (\n            <div\n              key={item.programId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                item.done ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · objectif{" "}\n                    {item.targetMode === "MAX"\n                      ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} a fond${\n                          item.personalBest ? ` (record : ${item.personalBest} ${unitLabel})` : ""\n                        }`\n                      : `${item.targetSets} x ${item.targetValue} ${unitLabel}`}\n                  </p>\n                </div>\n\n                {!isEditing && (\n                  <button\n                    onClick={() => (item.done ? undo(item) : startEditing(item))}\n                    className={`stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 ${\n                      item.done\n                        ? "bg-success/20 border-success text-success"\n                        : "bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                    }`}\n                    aria-label={item.done ? "Annuler la validation" : "Valider la seance"}\n                    title={item.done ? "Fait - clique pour annuler" : "Marquer comme fait"}\n                  >\n                    {item.done ? "✓" : ""}\n                  </button>\n                )}\n              </div>\n\n              {item.done && item.log && (\n                <p className="text-xs text-muted mt-2">\n                  Realise : {item.log.setsDone} x {item.log.valueDone} {unitLabel}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 flex items-end gap-3 flex-wrap bg-surface2 border border-border rounded-md p-3">\n                  <div>\n                    <label className="block text-xs text-muted mb-1">Series faites</label>\n                    <input\n                      type="number"\n                      min={0}\n                      value={sets}\n                      onChange={(e) => setSets(Number(e.target.value))}\n                      className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                    />\n                  </div>\n                  <div>\n                    <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                    <input\n                      type="number"\n                      min={0}\n                      value={value}\n                      onChange={(e) => setValue(Number(e.target.value))}\n                      className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                    />\n                  </div>\n                  <button\n                    onClick={() => confirm(item)}\n                    className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                  >\n                    Valider\n                  </button>\n                  <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                    Annuler\n                  </button>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Profile.tsx'] = 'import { FormEvent, useEffect, useState } from "react";\nimport { useAuth } from "../context/AuthContext";\nimport { api, ApiError } from "../api/client";\nimport { enablePushNotifications } from "../lib/push";\n\ninterface Badge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n  earned: boolean;\n  earnedAt: string | null;\n}\n\nexport default function Profile() {\n  const { user, refreshUser } = useAuth();\n  const [weightKg, setWeightKg] = useState(user?.weightKg?.toString() ?? "");\n  const [heightCm, setHeightCm] = useState(user?.heightCm?.toString() ?? "");\n  const [birthDate, setBirthDate] = useState(user?.birthDate?.slice(0, 10) ?? "");\n  const [sex, setSex] = useState(user?.sex ?? "");\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [badges, setBadges] = useState<Badge[] | null>(null);\n\n  useEffect(() => {\n    api.get<Badge[]>("/badges").then(setBadges);\n  }, []);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      await api.put("/users/me", {\n        weightKg: weightKg ? Number(weightKg) : null,\n        heightCm: heightCm ? Number(heightCm) : null,\n        birthDate: birthDate || null,\n        sex: sex || null,\n      });\n      await refreshUser();\n      setMessage("Profil mis a jour.");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de mettre a jour le profil.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function onEnableNotifications() {\n    setMessage(null);\n    setError(null);\n    try {\n      const result = await enablePushNotifications();\n      setMessage(result);\n    } catch {\n      setError("Impossible d\'activer les notifications sur cet appareil.");\n    }\n  }\n\n  return (\n    <div className="max-w-lg">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Mon profil</h1>\n      <p className="text-muted text-sm mb-6">Ces infos sont juste pour toi, pas partagees avec les autres membres.</p>\n\n      <form onSubmit={onSubmit} className="bg-surface border border-border rounded-xl p-6 space-y-4">\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="weight">\n              Poids (kg)\n            </label>\n            <input\n              id="weight"\n              type="number"\n              step="0.1"\n              min="0"\n              value={weightKg}\n              onChange={(e) => setWeightKg(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="height">\n              Taille (cm)\n            </label>\n            <input\n              id="height"\n              type="number"\n              step="0.1"\n              min="0"\n              value={heightCm}\n              onChange={(e) => setHeightCm(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="birthDate">\n            Date de naissance\n          </label>\n          <input\n            id="birthDate"\n            type="date"\n            value={birthDate}\n            onChange={(e) => setBirthDate(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sex">\n            Sexe (optionnel)\n          </label>\n          <select\n            id="sex"\n            value={sex}\n            onChange={(e) => setSex(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Ne souhaite pas preciser</option>\n            <option value="F">Femme</option>\n            <option value="M">Homme</option>\n            <option value="AUTRE">Autre</option>\n          </select>\n        </div>\n\n        {message && <p className="text-sm text-success">{message}</p>}\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n      </form>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Rappels</h2>\n        <p className="text-muted text-sm mb-4">\n          Active les notifications pour recevoir un rappel les jours ou une seance est prevue.\n        </p>\n        <button\n          onClick={onEnableNotifications}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Activer les notifications\n        </button>\n      </div>\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Mes badges</h2>\n        <p className="text-muted text-sm mb-4">\n          Bases sur ta regularite personnelle uniquement, pas de comparaison avec les autres membres.\n        </p>\n        {badges === null && <p className="text-muted text-sm">Chargement...</p>}\n        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">\n          {badges?.map((b) => (\n            <div\n              key={b.key}\n              title={b.description}\n              className={`rounded-lg p-3 text-center border ${\n                b.earned ? "bg-accent/10 border-accent" : "bg-surface2 border-border opacity-40"\n              }`}\n            >\n              <p className="text-2xl mb-1">{b.emoji}</p>\n              <p className="text-xs font-medium">{b.name}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Dashboard.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface CampSummary {\n  id: string;\n  name: string;\n  code: string;\n  exercises: { exercise: { id: string; name: string } }[];\n  _count: { members: number };\n}\n\nexport default function Dashboard() {\n  const [camps, setCamps] = useState<CampSummary[] | null>(null);\n\n  useEffect(() => {\n    api.get<CampSummary[]>("/camps/mine").then(setCamps);\n  }, []);\n\n  return (\n    <div>\n      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Mes camps</h1>\n          <p className="text-muted text-sm">Les groupes d\'entrainement auxquels tu participes.</p>\n        </div>\n        <div className="flex gap-2">\n          <Link\n            to="/camps/rejoindre"\n            className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n          >\n            Integrer un camp\n          </Link>\n          <Link\n            to="/camps/creer"\n            className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm"\n          >\n            + Nouveau camp\n          </Link>\n        </div>\n      </div>\n\n      {camps === null && <p className="text-muted">Chargement...</p>}\n\n      {camps?.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="font-display text-xl uppercase tracking-wide mb-2">Aucun camp pour l\'instant</p>\n          <p className="text-muted text-sm mb-5">\n            Cree ton premier camp d\'entrainement, ou rejoins celui de quelqu\'un d\'autre avec son code.\n          </p>\n        </div>\n      )}\n\n      <div className="grid gap-4 sm:grid-cols-2">\n        {camps?.map((camp) => (\n          <Link\n            key={camp.id}\n            to={`/camps/${camp.id}`}\n            className="bg-surface border border-border rounded-xl p-5 hover:border-accent/50 transition-colors"\n          >\n            <div className="flex items-center justify-between mb-2">\n              <h2 className="font-display text-lg uppercase tracking-wide">{camp.name}</h2>\n              <span className="font-mono text-xs bg-surface2 border border-border rounded px-2 py-1 text-muted">\n                {camp.code}\n              </span>\n            </div>\n            <p className="text-sm text-muted mb-1">\n              {camp.exercises.length} exercice{camp.exercises.length > 1 ? "s" : ""} · {camp._count.members} membre\n              {camp._count.members > 1 ? "s" : ""}\n            </p>\n            <p className="text-xs text-muted truncate">\n              {camp.exercises.map((e) => e.exercise.name).join(" · ")}\n            </p>\n          </Link>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/ExerciseRepository.tsx'] = 'import { useEffect, useMemo, useState } from "react";\nimport { api } from "../api/client";\n\ninterface ExerciseStat {\n  id: string;\n  name: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  isCustom: boolean;\n  campCount: number;\n}\n\nexport default function ExerciseRepository() {\n  const [exercises, setExercises] = useState<ExerciseStat[] | null>(null);\n  const [search, setSearch] = useState("");\n\n  useEffect(() => {\n    api.get<ExerciseStat[]>("/exercises/stats").then(setExercises);\n  }, []);\n\n  const filtered = useMemo(() => {\n    if (!exercises) return [];\n    const sorted = [...exercises].sort((a, b) => b.campCount - a.campCount);\n    return sorted.filter((e) => e.name.toLowerCase().includes(search.toLowerCase()));\n  }, [exercises, search]);\n\n  return (\n    <div className="max-w-2xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Repertoire d\'exercices</h1>\n      <p className="text-muted text-sm mb-6">\n        Tout le catalogue disponible, avec le nombre de camps qui utilisent chaque exercice (tous les camps de\n        l\'application, pas seulement les tiens).\n      </p>\n\n      <input\n        placeholder="Rechercher un exercice..."\n        value={search}\n        onChange={(e) => setSearch(e.target.value)}\n        className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-4"\n      />\n\n      {exercises === null && <p className="text-muted">Chargement...</p>}\n\n      <div className="space-y-2">\n        {filtered.map((exo) => (\n          <div\n            key={exo.id}\n            className="bg-surface border border-border rounded-lg p-4 flex items-center justify-between gap-3"\n          >\n            <div>\n              <p className="font-medium">\n                {exo.name}\n                {exo.isCustom && (\n                  <span className="ml-2 text-[10px] uppercase tracking-wide text-muted border border-border rounded px-1.5 py-0.5">\n                    maison\n                  </span>\n                )}\n              </p>\n              {exo.description && <p className="text-xs text-muted mt-0.5">{exo.description}</p>}\n            </div>\n            <div className="text-right shrink-0">\n              <p className="font-display text-lg text-accent">{exo.campCount}</p>\n              <p className="text-[10px] uppercase tracking-wide text-muted">\n                camp{exo.campCount > 1 ? "s" : ""}\n              </p>\n            </div>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'

